from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = "notes"


def read_note(name: str) -> str:
    """Return the text of the file ``name`` inside the ``notes`` directory.

    ``notes`` is resolved relative to the current working directory. Only
    regular files that resolve to a location inside ``notes`` are read.
    Any name that escapes the directory (``..`` segments, absolute paths,
    symlinks pointing outside, NUL bytes) is refused. A missing, unreadable,
    or refused file yields an empty string.
    """
    try:
        if "\x00" in name:
            return ""
        base = Path(NOTES_DIR).resolve()
        target = (base / name).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, RuntimeError, ValueError):
        return ""


@pytest.fixture
def notes_root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Create ``notes/`` under a temporary cwd, with a secret file beside it."""
    monkeypatch.chdir(tmp_path)
    root = tmp_path / NOTES_DIR
    root.mkdir()
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    return root


def test_reads_existing_note(notes_root: Path) -> None:
    (notes_root / "todo.txt").write_text("buy milk", encoding="utf-8")
    assert read_note("todo.txt") == "buy milk"


def test_reads_note_in_subdirectory(notes_root: Path) -> None:
    (notes_root / "work").mkdir()
    (notes_root / "work" / "plan.txt").write_text("ship it", encoding="utf-8")
    assert read_note("work/plan.txt") == "ship it"


def test_missing_file_is_empty(notes_root: Path) -> None:
    assert read_note("nope.txt") == ""


def test_directory_is_empty(notes_root: Path) -> None:
    (notes_root / "sub").mkdir()
    assert read_note("sub") == ""


def test_empty_name_is_empty(notes_root: Path) -> None:
    assert read_note("") == ""


@pytest.mark.parametrize(
    "name",
    [
        "../secret.txt",
        "sub/../../secret.txt",
        "./../secret.txt",
        "..",
        "../notes/../secret.txt",
    ],
)
def test_parent_traversal_is_refused(notes_root: Path, name: str) -> None:
    assert read_note(name) == ""


def test_absolute_path_outside_is_refused(notes_root: Path, tmp_path: Path) -> None:
    absolute = str((tmp_path / "secret.txt").resolve())
    assert read_note(absolute) == ""


def test_nul_byte_is_refused(notes_root: Path) -> None:
    (notes_root / "a.txt").write_text("A", encoding="utf-8")
    assert read_note("a.txt\x00../secret.txt") == ""


def test_symlink_pointing_outside_is_refused(notes_root: Path, tmp_path: Path) -> None:
    (notes_root / "link.txt").symlink_to(tmp_path / "secret.txt")
    assert read_note("link.txt") == ""


def test_symlink_inside_notes_is_followed(notes_root: Path) -> None:
    (notes_root / "real.txt").write_text("inside", encoding="utf-8")
    (notes_root / "alias.txt").symlink_to(notes_root / "real.txt")
    assert read_note("alias.txt") == "inside"
